    int izquierda = leer_numero(lector);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '*') {
            const int derecha = leer_numero(lector);
            izquierda = resultado_en_dominio(izquierda * derecha);
        } else if (token.clase == '/') {
            const int derecha = leer_numero(lector);
            if (derecha == 0) {
                throw std::runtime_error("Divisor cero");
            }
            izquierda = resultado_en_dominio(izquierda / derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_expresion(Lector_tokens& lector) {
    int izquierda = leer_termino(lector);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '+') {
