            const int derecha = leer_termino(lector);
            izquierda = resultado_en_dominio(izquierda - derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_operacion(Lector_tokens& lector) {
    const int resultado = leer_expresion(lector);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
    return resultado;
}

int main() {
    Lector_tokens lector{"6+2*5-3;"};
