    int izquierda = leer_numero(lector);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '*') {
            const int derecha = leer_numero(lector);
            izquierda = resultado_en_dominio(izquierda * derecha);
        } else if (token.clase == '/') {
            const int derecha = leer_numero(lector);
            if (derecha == 0) {
                throw std::runtime_error("Divisor cero");
            }
            izquierda = resultado_en_dominio(izquierda / derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_expresion(Lector_tokens& lector) {
    int izquierda = leer_termino(lector);
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '+') {
            const int derecha = leer_termino(lector);
            izquierda = resultado_en_dominio(izquierda + derecha);

        } else if (token.clase == '-') {
            const int derecha = leer_termino(lector);
            izquierda = resultado_en_dominio(izquierda - derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_operacion(Lector_tokens& lector) {
    const int resultado = leer_expresion(lector);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
    return resultado;
}

int main() {
    Lector_tokens lector{"3+11/2*2;"};
    try {
        const int resultado = leer_operacion(lector);
        const Token extra = lector.leer();
        if (extra.clase != 'f') {
            throw std::runtime_error("Texto extra tras la operacion");
        }
        std::cout << "Resultado: " << resultado;
    } catch (const std::runtime_error& error) {
        std::cout << "Error: " << error.what();
    }
    return 0;
}
